/**
 * Shared types used across automations, agents, and other EDK domains.
 */
import { EdkValidationError } from "../../../../elementum-entity-client/errors.js";
export function asc(field) {
    return { field, direction: "ASC" };
}
export function desc(field) {
    return { field, direction: "DESC" };
}
/** Multi-field sort (order is significant). Serializes to `Sort.orders` for Mobius. */
export function sortBy(...orders) {
    if (orders.length === 0) {
        throw new EdkValidationError("sortBy requires at least one sort order.");
    }
    return orders;
}
/**
 * Defensive runtime predicate — confirms a `unknown` value matches the
 * authored `SortOrder` shape (`{ field: { id }, direction }`). The
 * serializer accepts `SortOrder | SortOrder[] | unknown` from callers
 * (the public option type is loose enough that an arbitrary object
 * could land here) so this guards against bad input before we project
 * onto the wire. Used by {@link serializeSortToWire}.
 */
function isSortOrderLike(v) {
    if (v === null || typeof v !== "object" || Array.isArray(v))
        return false;
    const o = v;
    const field = o.field;
    if (field === null || typeof field !== "object" || !("id" in field))
        return false;
    return typeof field.id === "string" && typeof o.direction === "string";
}
/**
 * Serialize an authored `SortOrder | readonly SortOrder[]` to the
 * platform's `Sort` JSON shape: `{ orders: [{ field: <id>, direction }] }`.
 * Returns `undefined` when `sort` is null/undefined or doesn't match
 * the expected shape — callers can then omit the wire field entirely.
 *
 * Lifted from `automations/serializer/task-serializer.ts` so every
 * tool surface that accepts a sort (automation `recordSearch`, agent
 * search tools, etc.) emits the same wire shape through the same
 * code path.
 */
export function serializeSortToWire(sort) {
    if (sort == null || typeof sort !== "object")
        return undefined;
    let clauses;
    if (Array.isArray(sort)) {
        clauses = sort.filter(isSortOrderLike);
    }
    else if (isSortOrderLike(sort)) {
        clauses = [sort];
    }
    else {
        clauses = [];
    }
    if (clauses.length === 0)
        return undefined;
    return {
        orders: clauses.map((o) => ({ field: o.field.id, direction: o.direction })),
    };
}
